const eventVisual = (id) => haitiEvents.find((event) => event.id === id)?.visual;
const curriculumFor = (date) => {
  if (date <= 1859) return 'UA6 — Haïti de 1804 à 1859 : constructions de l’État, constitutions et formes de pouvoir.';
  if (date < 1915) return 'UA7 et UA8 — sociétés, travail et infrastructures; dette, diplomatie, impérialismes et souveraineté. Le programme ne prescrit pas une biographie de chaque président.';
  return 'UA9 — crises et guerres : occupation de 1915–1934, gouvernements de 1934–1957, régimes Duvalier et transition de 1986–1987. Le programme ne prescrit pas une biographie de chaque président.';
};

const make = function make(id, date, dateLabel, period, name, officeTitle, summary, context, achievements, limits, consequences, image, sources, extra = {}) {
  // Accepte aussi les fiches enrichies avec un paragraphe de développement distinct.
  if (typeof achievements === 'string') {
    const development = achievements;
    achievements = limits;
    limits = consequences;
    consequences = image;
    image = sources;
    sources = extra;
    extra = arguments[14] || {};
    context = `${context} ${development}`;
  }
  const missingVisuals = {
    roy: images.roy,
    'pierre-louis': images.pierreLouis,
    sylvain: images.sylvain,
    fignole: images.fignole,
    kebreau: images.kebreau,
    'jean-claude-duvalier': images.jeanClaude,
  };
  const visual = image || missingVisuals[id];
  const supplementalGallery = {
    'francois-duvalier': [images.duvalierCampaign1957],
    'jean-claude-duvalier': [],
    kebreau: [images.kebreauPortrait, images.duvalierCampaign1957],
  }[id] || [];
  const gallery = (extra.gallery || supplementalGallery.length)
    ? [...(extra.gallery || []), ...supplementalGallery]
    : undefined;
  return ({
  id, date, dateLabel, period, title: name, officeTitle, summary, context,
  development: `${summary} ${context}`,
  achievements: achievements.map((text) => ({ label: text })),
  limitations: limits.map((text) => ({ label: text })),
  consequences, concepts: extra.concepts || ['État', 'pouvoir politique', 'sources historiques'],
  actors: [name, ...(extra.actors || [])], sources: [refs.list, ...sources],
  curriculum: extra.curriculum || curriculumFor(date),
  uncertainty: extra.uncertainty || 'Les dates de transition peuvent varier selon les chronologies, notamment lorsque le pouvoir est contesté ou exercé simultanément dans plusieurs régions. La notice d’image précise si elle est contemporaine ou rétrospective.',
  ...(visual ? { visual } : {}), ...(gallery ? { gallery } : {}),
  });
};

const nyplCore = [refs.casimir, refs.stieber, refs.nyplNotice];
const earlySources = [refs.early, refs.casimir, refs.stieber];
const nineteenthSources = [refs.casimir, refs.stieber];
const occupationSources = [refs.occupation, refs.locOccupation, refs.navyOccupation, refs.haitiLabOccupation, refs.casimir];
const modernSources = [refs.postOccupation, refs.chronology, refs.casimir];
const duvalierSources = [refs.duvalier, refs.chronology, refs.iachr79, refs.rights];

const leaders = [
  make('dessalines',1804,'1804–1806','Indépendance et premier Empire','Jean-Jacques Dessalines','Gouverneur général puis empereur Jacques Ier','Il proclame l’indépendance le 1er janvier 1804 et fonde le premier Empire d’Haïti en 1805.','Le nouvel État cherche à défendre son indépendance dans un monde esclavagiste et colonial qui refuse de la reconnaître. La Constitution de 1805 organise un pouvoir impérial et interdit l’esclavage.', ['Indépendance d’Haïti et création d’un État souverain.','Constitution de 1805 et organisation d’un pouvoir central.'], ['Le travail agricole obligatoire et les réquisitions suscitent de fortes résistances.','Le pouvoir très centralisé ne règle pas le partage des terres et des richesses.'], 'Après son assassinat en 1806, le pays se divise entre plusieurs gouvernements; son héritage reste central dans les mémoires de la révolution.',images.dessalines,[refs.casimir,refs.stieber],{gallery:[images.citadelle],concepts:['indépendance','Empire','Constitution de 1805','assassinat politique'],uncertainty:'La gravure NYPL publiée en 1888 est une représentation rétrospective; elle ne permet pas de connaître fidèlement l’apparence de Dessalines.'}),
  make('petion',1807,'1807–1818','Deux gouvernements, Nord et Sud','Alexandre Pétion','Président de la République du Sud et de l’Ouest','Après la rupture de 1806, Pétion dirige le gouvernement républicain du Sud et de l’Ouest jusqu’à sa mort.','Son gouvernement rivalise avec celui d’Henri Christophe dans le Nord. La République de Pétion s’appuie sur le Sénat et un régime républicain; la distribution de terres aux soldats et cultivateurs contribue à l’émergence de petites propriétés.', ['Maintien d’institutions républicaines et d’une constitution.','Distribution de terres à des soldats et cultivateurs, avec des effets durables sur la propriété rurale.'], ['La petite propriété progresse sans transformer l’ensemble des inégalités économiques.','La division politique affaiblit l’unité du nouvel État.'], 'La coexistence de deux États haïtiens éclaire les débats sur la forme du pouvoir et la question agraire après l’indépendance.',images.petion,nyplCore,{gallery:[images.christophe],uncertainty:'Le portrait est une gravure publiée en 1888 et non une photographie de Pétion.'}),
  make('christophe',1807,'1807–1820','Deux gouvernements, Nord et Sud','Henri Christophe','Président de l’État du Nord puis roi Henri Ier','Christophe dirige le Nord à partir de 1807, d’abord comme président puis comme roi après la création du Royaume d’Haïti en 1811.','Le royaume développe une administration et un appareil militaire distincts. Après la guerre d’indépendance, des fortifications et de grands chantiers répondent à la crainte d’une nouvelle invasion.', ['Construction de la Citadelle Laferrière et du palais Sans-Souci.','Développement d’écoles et d’institutions au sein du royaume.'], ['Le régime impose un travail agricole et des corvées sévères.','Les chantiers mobilisent une main-d’œuvre sous forte contrainte et le pouvoir est monarchique.'], 'La révolution de 1820 met fin au royaume et rend possible la réunification politique sous Boyer.',images.christophe,[...nyplCore],{gallery:[images.citadelle],uncertainty:'Le portrait est une gravure de 1888; la vue de la Citadelle est une illustration de la même publication, pas un dossier photographique des travaux.'}),
  make('boyer',1818,'1818–1843','Réunification et gouvernement de Boyer','Jean-Pierre Boyer','Président d’Haïti','Boyer succède à Pétion dans le Sud en 1818, réunit le Nord en 1820 et gouverne l’ensemble de l’île jusqu’en 1843.','Son administration établit une unité territoriale, puis étend son autorité à la partie orientale de l’île en 1822. La France reconnaît Haïti en 1825 en échange d’une indemnité très lourde.', ['Réunification du Nord et du Sud en 1820.','Reconnaissance française de l’indépendance en 1825, malgré ses conditions financières imposées.'], ['Le Code rural de 1826 encadre durement le travail paysan et limite la mobilité.','L’indemnité et les emprunts qui la financent pèsent durablement sur les finances publiques.'], 'La contestation du régime et de ses politiques contribue à la crise de 1843 et à sa chute; l’indépendance dominicaine est proclamée en 1844.',images.boyer,[...nyplCore,refs.early],{gallery:[images.petion],uncertainty:'La gravure publiée en 1888 n’est pas un portrait contemporain. Les effets concrets de l’indemnité varient selon les groupes et périodes étudiées.'}),
  make('riviere-herard',1843,'1843–1844','Crises et gouvernements du XIXe siècle','Charles Rivière-Hérard','Président d’Haïti','La révolution de 1843 renverse Boyer et porte Rivière-Hérard à la tête de l’État après une période de transition.','Le gouvernement affronte la crise financière, la mobilisation paysanne et le mouvement d’indépendance à l’est. Le Code rural est abrogé en 1843, mais les tensions persistent.', ['Abrogation du Code rural de 1826.','Révision politique après la chute d’un gouvernement de près de vingt-cinq ans.'], ['La campagne contre les indépendantistes dominicains échoue.','Le gouvernement est rapidement contesté et renversé.'], 'Une succession rapide de régimes marque les années 1840 et rend visible la fragilité des institutions.',images.riviere,earlySources,{uncertainty:'La gravure NYPL de 1888 est rétrospective. Les dates exactes et statuts du gouvernement de 1843 diffèrent légèrement selon les chronologies.'}),
  make('guerrier',1844,'1844–1845','Crises et gouvernements du XIXe siècle','Philippe Guerrier','Président d’Haïti','Guerrier arrive au pouvoir après la chute de Rivière-Hérard, dans un contexte de crise institutionnelle et de séparation de la partie orientale de l’île.','Le gouvernement tente de rétablir une autorité nationale après les conflits de 1843–1844. Le mandat est bref et s’achève avec sa mort.', ['Rétablissement provisoire d’une direction exécutive après la révolution de 1843.'], ['La succession continue de dépendre des alliances militaires et politiques.','Les institutions restent fragiles et les réformes sont limitées par la durée du mandat.'], 'Après sa mort, le pouvoir passe à Jean-Louis Pierrot, dont l’autorité est contestée dans le Nord.',images.guerrier,earlySources,{uncertainty:'La gravure NYPL date de 1888, plusieurs décennies après le mandat.'}),
  make('pierrot',1845,'1845–1846','Crises et gouvernements du XIXe siècle','Jean-Louis Pierrot','Président d’Haïti','Pierrot est choisi après la mort de Guerrier, mais son autorité rencontre une forte opposition et est contestée dans le Nord.','Les archives de cette période montrent des transitions rapides, des conflits régionaux et une difficulté à faire appliquer une autorité centrale.', ['Maintien d’une continuité exécutive malgré la crise.'], ['Son gouvernement est renversé dans un contexte de contestation régionale.','L’autorité de l’État demeure inégale selon les territoires.'], 'La crise ouvre la voie à la présidence de Jean-Baptiste Riché.',images.pierrot,earlySources,{uncertainty:'Les chronologies ne décrivent pas toutes de la même manière l’étendue du contrôle exercé par Pierrot.'}),
  make('riche',1846,'1846–1847','Crises et gouvernements du XIXe siècle','Jean-Baptiste Riché','Président d’Haïti','Riché gouverne après la chute de Pierrot et rétablit des dispositions constitutionnelles de la période antérieure.','Il rétablit la Constitution de 1816 et des conseils communaux; la présidence à vie y demeure, révélant la tension entre stabilité institutionnelle et représentation.', ['Rétablissement d’institutions communales et de dispositions constitutionnelles.'], ['La présidence à vie limite l’alternance démocratique.','La participation politique reste étroite et les crises de succession persistent.'], 'À sa mort, Soulouque devient président puis rétablit l’Empire.',images.riche,earlySources,{uncertainty:'La gravure NYPL de 1888 est rétrospective.'}),
  make('soulouque',1847,'1847–1859','Empire de Faustin Ier','Faustin Soulouque','Président puis empereur Faustin Ier','Élu président en 1847, Soulouque devient empereur en 1849 sous le nom de Faustin Ier.','L’Empire cherche à consolider le pouvoir et lance plusieurs campagnes vers l’est de l’île. La cour et les institutions impériales structurent la vie politique.', ['Rétablissement d’un pouvoir central après des années de crises.','Développement d’institutions et de symboles impériaux haïtiens.'], ['Campagnes militaires coûteuses et répression des opposants.','Le pouvoir impérial restreint l’alternance et prend fin par une révolution en 1859.'], 'La chute de l’Empire ouvre une nouvelle République et la présidence de Fabre Geffrard.',images.soulouque,[...earlySources,refs.casimir],{actors:['Faustin Ier'],uncertainty:'Les bilans de son règne divergent selon les auteurs; les campagnes et la répression doivent être décrites avec des sources distinctes.'}),
  make('geffrard',1859,'1859–1867','République et crises du XIXe siècle','Fabre Geffrard','Président d’Haïti','Geffrard renverse Soulouque et dirige la République jusqu’en 1867.','Son gouvernement conclut un concordat avec le Saint-Siège en 1860, obtient la reconnaissance diplomatique des États-Unis en 1862 et soutient l’enseignement.', ['Concordat de 1860 et développement de l’enseignement, notamment rural.','Reconnaissance diplomatique américaine en 1862.'], ['La police rurale et les obligations de travail restent coercitives.','Les oppositions et les soulèvements se poursuivent; Geffrard quitte le pouvoir en 1867.'], 'La fin du régime est suivie par la présidence contestée de Salnave.',images.geffrard,[...earlySources,refs.list],{curriculum:'UA6 — construction de l’État; UA8 — relations internationales et impérialismes.'}),
  make('salnave',1867,'1867–1869','République et crises du XIXe siècle','Sylvain Salnave','Président d’Haïti','Salnave accède au pouvoir après la chute de Geffrard, alors que des insurrections divisent le pays.','Son gouvernement s’appuie sur l’armée dans un contexte de guerre civile et d’affrontements entre factions. Il est capturé et exécuté après sa défaite.', ['Tentative de réunir les pouvoirs concurrents pendant une guerre civile.'], ['La guerre civile et l’exécution du président montrent l’extrême violence de la crise politique.'], 'La présidence est exercée par un gouvernement provisoire avant l’arrivée de Nissage Saget.',images.salnave,nineteenthSources,{uncertainty:'Les gouvernements rivaux et les dates d’autorité effective sont à distinguer des dates de titre.'}),
  make('saget',1870,'1870–1874','République et crises du XIXe siècle','Nissage Saget','Président d’Haïti','Saget gouverne après une période de guerre civile et de transition provisoire.','Il tente de gouverner dans le cadre d’institutions républicaines et de limites constitutionnelles, mais les rivalités politiques et les pressions étrangères persistent.', ['Tentative de séparation des pouvoirs et de fonctionnement constitutionnel.'], ['Les rivalités entre exécutif et législatif limitent la stabilité gouvernementale.','Des pressions diplomatiques et des conflits internes pèsent sur le régime.'], 'La fin du mandat ouvre une nouvelle crise qui porte Michel Domingue au pouvoir.',images.saget,nineteenthSources,{uncertainty:'Le portrait NYPL, publié en 1888, est une gravure rétrospective.'}),
  make('domingue',1874,'1874–1876','République et crises du XIXe siècle','Michel Domingue','Président d’Haïti','Domingue gouverne pendant une période de tensions régionales et de conflits autour de l’autorité exécutive.','La constitution et les institutions formelles ne suffisent pas à régler les rivalités politiques ni les difficultés financières.', ['Maintien d’une administration nationale en période de conflit politique.'], ['Le gouvernement est accusé de corruption et tombe après une insurrection.'], 'Boisrond-Canal lui succède après la transition de 1876.',images.domingue,nineteenthSources),
  make('boisrond-canal',1876,'1876–1879','République et crises du XIXe siècle','Pierre Théoma Boisrond-Canal','Président d’Haïti','Boisrond-Canal arrive au pouvoir après la chute de Domingue et dirige un régime soumis aux pressions parlementaires et aux conflits armés.','Le cadre républicain se consolide par moments, mais les coalitions gouvernementales demeurent instables.', ['Réouverture de la vie politique après le renversement de Domingue.'], ['La guerre civile de 1879 entraîne son départ du pouvoir.'], 'La révolution de 1879 permet l’arrivée de Lysius Salomon.',images.boisrond,nineteenthSources),
  make('salomon',1879,'1879–1888','Modernisation et crises du XIXe siècle','Lysius Salomon','Président d’Haïti','Salomon mène un programme de modernisation de l’État et des communications pendant près de neuf ans.','Son gouvernement soutient des écoles, l’agriculture, le télégraphe, la banque et l’intégration postale internationale. Les projets et leurs réalisations doivent être distingués.', ['Développement de l’enseignement, des communications et de services publics.','Adhésion à l’Union postale universelle et mise en place d’une banque nationale.'], ['Les amendements constitutionnels et les conflits de succession renforcent l’opposition.','L’insurrection de 1888 entraîne la chute du régime.'], 'Les luttes de pouvoir se poursuivent en 1888–1889 et débouchent sur la présidence d’Hyppolite.',images.salomonPortrait,nineteenthSources,{gallery:[images.salomonFall],curriculum:'UA6 — institutions; UA7 — économies, travail et infrastructures; UA8 — banque, dette et impérialismes.'}),
  make('legitime',1888,'1888–1889','Transitions et gouvernements rivaux','François Denys Légitime','Président contesté à Port-au-Prince','Après la chute de Salomon, Légitime est proclamé président dans la capitale, tandis qu’un gouvernement du Nord conteste son autorité.','La crise de 1888 oppose des coalitions politiques et régionales; elle ne correspond pas à une succession nationale paisible.', ['Tentative de rétablissement d’une administration après la crise de 1888.'], ['Son autorité n’est pas acceptée dans tout le pays et le gouvernement est renversé en 1889.'], 'La crise débouche sur la présidence de Florvil Hyppolite.',images.legitime,[...nineteenthSources,refs.chronology],{uncertainty:'Légitime doit être présenté comme président contesté et non comme détenteur d’une autorité incontestée sur tout le territoire. La photo de la collection Bain n’a pas de date précise.'}),
  make('hyppolite',1889,'1889–1896','Modernisation et crises du XIXe siècle','Florvil Hyppolite','Président d’Haïti','Hyppolite gouverne après la crise des gouvernements rivaux et investit dans des travaux publics et les communications.','Son gouvernement développe notamment le télégraphe et des projets d’infrastructure. Les puissances étrangères convoitent des positions stratégiques dans les Caraïbes.', ['Travaux publics et amélioration de communications télégraphiques.','Résistance à une concession étrangère stratégique à Môle-Saint-Nicolas.'], ['L’opposition est réprimée et le pouvoir dépend fortement de l’armée.'], 'Son décès en fonction ouvre une succession moins violente sous Tirésias Simon Sam.',images.hyppolite,nineteenthSources,{curriculum:'UA7 — infrastructures et transformation économique; UA8 — impérialismes et souveraineté.'}),
  make('simon-sam',1896,'1896–1902','Modernisation et crises du XIXe siècle','Tirésias Simon Sam','Président d’Haïti','Simon Sam est élu après la mort d’Hyppolite et gouverne jusqu’à sa démission en 1902.','Les projets d’infrastructure et la diplomatie coexistent avec la dette et les rivalités politiques. La succession débouche sur une guerre civile.', ['Poursuite de travaux publics et de projets de modernisation.'], ['L’État reste fragilisé par les dettes, les rivalités et une succession contestée.'], 'La chute du gouvernement ouvre une guerre civile et la présidence de Nord Alexis.',images.simonSam,nineteenthSources,{uncertainty:'Le portrait de la New York Public Library a été publié en 1910, après son mandat.'}),
  make('nord-alexis',1902,'1902–1908','Crises et transformations au début du XXe siècle','Pierre Nord Alexis','Président d’Haïti','Nord Alexis arrive au pouvoir après une guerre civile et gouverne pendant une période de contestation et de conflits frontaliers.','Le début du XXe siècle voit les finances publiques sous pression et l’influence étrangère croître dans la région.', ['Rétablissement temporaire d’une administration centrale après la guerre civile.'], ['La répression politique et le conflit de succession contribuent à son renversement.'], 'La présidence passe à Antoine Simon en 1908.',images.nordAlexis,[...nineteenthSources,refs.occupation]),
  make('antoine-simon',1908,'1908–1911','Crises et transformations au début du XXe siècle','Antoine Simon','Président d’Haïti','Antoine Simon prend le pouvoir après la chute de Nord Alexis, avec un soutien régional important.','Son gouvernement tente des projets de modernisation et des investissements, mais les oppositions armées et les contraintes financières s’intensifient.', ['Relance de projets de travaux publics et d’aménagement.'], ['Les conflits régionaux et les finances publiques fragiles compromettent le régime.'], 'Une révolution entraîne son départ et ouvre la succession de Cincinnatus Leconte.',images.antoineSimon,nineteenthSources),
  make('leconte',1911,'1911–1912','Crises et transformations au début du XXe siècle','Cincinnatus Leconte','Président d’Haïti','Leconte accède à la présidence après une révolution et lance des mesures de réforme administrative et militaire.','Il meurt lors de l’explosion du palais national en 1912. Les causes de l’explosion sont disputées et ne peuvent être affirmées sans réserve.', ['Tentatives de réforme de l’armée et de l’administration.'], ['Le conflit politique demeure violent et le décès du président plonge le pays dans une nouvelle transition.'], 'La succession de Tancrède Auguste reste brève et la crise politique s’aggrave jusqu’à l’occupation de 1915.',images.leconte,nineteenthSources,{uncertainty:'Les causes de l’explosion de 1912 ne sont pas établies de manière consensuelle.'}),
  make('tancrede-auguste',1912,'1912–1913','Crises et transformations au début du XXe siècle','Tancrède Auguste','Président d’Haïti','Auguste devient président après la mort de Leconte et gouverne moins d’un an.','Les factions militaires et les difficultés de succession continuent de fragiliser l’État.', ['Maintien temporaire du gouvernement après l’explosion de 1912.'], ['Décès en fonction et durée courte limitent la continuité administrative.'], 'Michel Oreste prend la présidence en 1913.',images.tancrede,nineteenthSources),
  make('michel-oreste',1913,'1913–1914','Crises et transformations au début du XXe siècle','Michel Oreste','Président d’Haïti','Oreste est porté à la présidence par une période d’instabilité et de rivalités au sein de l’élite politique.','Le gouvernement fait face à des conflits armés et à des pressions liées aux finances et aux créanciers étrangers.', ['Succession institutionnelle temporaire après la mort de Tancrède Auguste.'], ['Il démissionne face à une insurrection et à l’effondrement de son soutien politique.'], 'Les présidences courtes d’Oreste Zamor et Davilmar Théodore précèdent la crise de 1915.',images.michelOreste,nineteenthSources),
  make('zamor',1914,'1914','Guerres civiles et occupation','Oreste Zamor','Président d’Haïti','Oreste Zamor gouverne pendant quelques mois au cours des guerres civiles de 1914.','Des rébellions opposent plusieurs factions; l’armée et les finances de l’État s’affaiblissent.', ['Tentative de conserver un exécutif en pleine guerre civile.'], ['Son gouvernement est renversé par les forces de Davilmar Théodore.'], 'La succession rapide déstabilise encore davantage l’État avant l’arrivée de Guillaume Sam.',images.zamor,nineteenthSources,{uncertainty:'La durée des mandats varie selon que l’on retient la prise effective de la capitale ou la proclamation officielle.'}),
  make('theodore',1914,'1914–1915','Guerres civiles et occupation','Davilmar Théodore','Président d’Haïti','Théodore devient président après la chute d’Oreste Zamor, dans un pays divisé par une guerre civile.','Le gouvernement ne parvient pas à rétablir l’ordre ni à contrôler toutes les factions armées.', ['Courte tentative de continuité gouvernementale.'], ['Il est renversé au début de 1915, au terme d’une succession de coups de force.'], 'Vilbrun Guillaume Sam lui succède avant l’intervention militaire américaine.',images.theodore,nineteenthSources,{uncertainty:'Les actes de succession sont rapides et parfois contestés.'}),
  make('guillaume-sam',1915,'Mars–juillet 1915','Guerres civiles et occupation','Vilbrun Guillaume Sam','Président d’Haïti','Guillaume Sam devient président en mars 1915 au terme d’une période de révoltes et de gouvernements successifs.','Le 27 juillet, des prisonniers politiques sont exécutés dans la capitale; le lendemain, une foule tue le président. Les États-Unis débarquent ensuite leurs Marines.', ['Tentative de réorganiser l’administration pendant une guerre civile.'], ['Les exécutions de détenus et le lynchage du président s’inscrivent dans une crise de violence politique.'], 'Le débarquement américain du 28 juillet 1915 inaugure une occupation qui dure jusqu’en 1934.',images.guillaumeSam,occupationSources,{curriculum:'UA9 — crises, guerres, intervention étrangère et occupation de 1915 à 1934.',uncertainty:'Le meurtre de Sam et le débarquement américain sont deux faits distincts; l’intervention avait aussi des causes stratégiques et financières documentées. Le portrait est une attribution Commons sans photographe identifié.'}),
  make('dartiguenave',1915,'1915–1922','Occupation américaine (1915–1934)','Philippe Sudré Dartiguenave','Président haïtien élu par l’Assemblée sous occupation','Sénateur et président du Sénat, Dartiguenave est choisi par l’Assemblée en août 1915, après le débarquement des Marines. L’élection se tient dans un rapport de force créé par l’intervention militaire américaine.','Le traité haïtiano-américain de septembre 1915 place les finances sous contrôle américain et autorise des conseillers étrangers dans des fonctions centrales. Dartiguenave conserve la présidence et des institutions haïtiennes subsistent, mais les décisions majeures sont encadrées par le Haut-Commissaire et les autorités militaires. En 1917, après le refus du Parlement d’approuver un premier projet constitutionnel, l’Assemblée est dissoute. La Constitution de 1918, ratifiée par plébiscite dans des conditions contestées, ouvre la propriété foncière aux étrangers; aucune législature représentative ne siégera à nouveau avant 1930.','La création de la Gendarmerie d’Haïti transforme l’appareil militaire et policier. Des travaux routiers, des services sanitaires et des réorganisations administratives sont menés sous occupation; il faut les lire avec le contrôle des finances, les impôts, le travail forcé et les objectifs stratégiques américains. La seconde insurrection caco de 1918–1920 est réprimée; Charlemagne Péralte est tué en 1919 puis Benoît Batraville en 1920.',['Des services publics, routes, ponts et installations sanitaires sont construits ou réorganisés, souvent sous direction ou financement des services du traité.','La Gendarmerie d’Haïti devient une institution durable de l’État.'],['La souveraineté budgétaire et militaire est fortement limitée.','La dissolution du Parlement et la Constitution de 1918 nourrissent une crise de légitimité.','La corvée routière, les violences de la Gendarmerie et les discriminations de l’occupation déclenchent des résistances paysannes.'], 'À la fin de son mandat, en 1922, le Conseil d’État élit Louis Borno. L’occupation et les résistances continuent; la présidence de Dartiguenave ne correspond donc pas à une période de gouvernement indépendant.',images.dartiguenave,[...occupationSources,refs.treaty1915,refs.constitution1918,refs.locJohnson],{gallery:[eventVisual('occupation-americaine-1915-1934')],curriculum:'UA9 — occupation américaine, 1915–1934; institutions, souveraineté, résistances et biographies politiques.',actors:['Conseil d’État','Marines des États-Unis','Gendarmerie d’Haïti','Assemblée nationale'],concepts:['occupation','tutelle financière','Constitution de 1918','corvée','souveraineté'],uncertainty:'Distinguer la justification officielle américaine des effets documentés et des interprétations haïtiennes. Le résultat du plébiscite constitutionnel ne suffit pas à établir un consentement libre et représentatif.'}),
  make('borno',1922,'1922–1930','Occupation américaine (1915–1934)','Louis Borno','Président haïtien sous occupation','Borno est élu en 1922 par le Conseil d’État, organe nommé qui exerce alors le rôle de législature. La population ne choisit pas directement le président. Il demeure au pouvoir jusqu’en 1930 sous une occupation qui conserve le contrôle des finances, de la sécurité et de décisions majeures.','La présidence de Borno est marquée par une centralisation de l’exécutif et par l’absence d’un Parlement élu. Son gouvernement travaille avec le Haut-Commissaire américain John H. Russell et les services du traité. Des routes, ponts, écoles, hôpitaux et services sanitaires sont développés, mais les rapports officiels américains vantant ces réalisations doivent être confrontés aux débats sur les taxes, l’endettement, la corvée, l’inégale répartition des travaux et la faible représentation politique. Les amendements constitutionnels de 1928 ne rétablissent pas immédiatement une législature élue.','Les grèves étudiantes et les mobilisations de 1929, culminant notamment à Les Cayes où des Marines tirent sur des manifestants haïtiens, mettent en évidence le rejet du régime d’occupation. Après l’enquête de la commission Forbes et les négociations avec les groupes d’opposition, Borno quitte le pouvoir en mai 1930; Louis-Eugène Roy lui succède comme président provisoire.',['Des routes et ponts sont construits; des services de santé publique, des hôpitaux et des écoles sont réorganisés.','Le gouvernement conduit une politique de centralisation et d’administration financière avec les autorités d’occupation.'],['Le Conseil d’État n’est pas élu par la population et réélit Borno; l’opposition parle de dictature et réclame le retour d’institutions représentatives.','L’occupation supervise une part importante des recettes et dépenses publiques; le remboursement de la dette et la fiscalité pèsent sur les finances nationales.','Les manifestations de 1929 et les morts de Les Cayes révèlent les coûts humains de la répression.'], 'L’évaluation des infrastructures s’appuie souvent sur des rapports de l’administration occupante, qui ont leurs propres objectifs. Les sources haïtiennes, les témoignages et les dossiers de la commission d’enquête donnent à voir les conflits et les voix opposées.',images.borno,[...occupationSources,refs.bornoElection,refs.forbesCommission],{gallery:[eventVisual('occupation-americaine-1915-1934')],curriculum:'UA9 — occupation, administration, constitution, dette, travail, contestations et transition de 1930.',actors:['Conseil d’État','John H. Russell, Haut-Commissaire','groupes patriotiques haïtiens','Commission Forbes'],concepts:['Conseil d’État','tutelle financière','représentation','corvée','contestation'],uncertainty:'Les bilans de travaux sont rapportés par la commission américaine de 1930; les chiffres et jugements doivent être attribués à cette source et confrontés aux témoignages haïtiens.'}),
  make('roy',1930,'15 mai–18 novembre 1930','Occupation américaine (1915–1934)','Louis-Eugène Roy','Président provisoire de la République','Roy devient président provisoire le 15 mai 1930 après un compromis négocié sous l’égide de la commission envoyée par le président Herbert Hoover. Il est acceptable aux groupes patriotiques et à Borno, mais les États-Unis interviennent directement dans la négociation et conditionnent leur reconnaissance du gouvernement.','La mission convenue est de rétablir une législature par des élections, puis de laisser l’Assemblée nationale élire un président pour le mandat régulier. Les élections législatives ont lieu en octobre 1930. Roy exerce donc un mandat de transition limité, au moment où le retrait américain est engagé mais où l’occupation n’est pas encore terminée.','Après la réunion de l’Assemblée nationale, Roy démissionne en novembre et les députés et sénateurs élisent Sténio Vincent le 18 novembre 1930.',['Organisation d’une transition vers des élections législatives en octobre 1930.','Rétablissement d’une Assemblée nationale appelée à choisir un président pour un mandat régulier.'],['Le compromis se négocie sous forte influence américaine; les groupes patriotiques réclament le retour de la souveraineté et d’un gouvernement représentatif.','Le mandat provisoire ne met pas fin à l’occupation ni au contrôle financier américain.'], 'Le retour d’une législature ouvre une nouvelle phase politique, mais la présence militaire américaine se poursuit jusqu’en août 1934 et la tutelle financière plus longtemps.',null,[...occupationSources,refs.forbesCommission,refs.royTransition,refs.vincentElection],{curriculum:'UA9 — gouvernements provisoires, élections de 1930, souveraineté et fin de l’occupation.',actors:['groupes patriotiques et opposition','Conseil d’État','Commission Forbes','Assemblée nationale'],concepts:['gouvernement provisoire','compromis politique','élection','souveraineté'],uncertainty:'Les documents diplomatiques décrivent les négociations depuis la position des États-Unis; ils doivent être lus avec les revendications des groupes haïtiens rapportées dans ces mêmes dossiers.'}),
  make('vincent',1930,'18 novembre 1930–1934 (occupation)','Occupation américaine (1915–1934)','Sténio Vincent','Président élu par l’Assemblée nationale','Ancien sénateur et opposant nationaliste à l’occupation, Vincent est élu président par l’Assemblée nationale le 18 novembre 1930, après les élections législatives d’octobre. Il gouverne Haïti pendant les dernières années de l’occupation américaine; son mandat présidentiel se poursuit ensuite jusqu’en 1941.','Vincent demande le retrait des Marines et cherche à restaurer l’autonomie politique haïtienne. Le 14 août 1934, le retrait officiel met fin à l’occupation militaire, mais ne fait pas disparaître immédiatement l’influence économique américaine ni le contrôle financier établi pendant le traité. Dans les années suivantes, le gouvernement Vincent renforce le pouvoir présidentiel; la Constitution de 1935 appartient à l’après-occupation et doit être étudiée séparément.',['La fin de l’occupation militaire en août 1934 rétablit le contrôle haïtien sur les fonctions exercées par les Marines.','La présidence rend davantage visibles le nationalisme haïtien et les revendications d’autonomie.'],['Le départ des Marines n’efface pas la dépendance financière et les rapports économiques construits sous occupation.','Les tendances autoritaires ultérieures de Vincent et la Constitution de 1935 relèvent de l’après-occupation, mais éclairent les limites de la transition.'], 'Le 14 août 1934 marque la fin de l’occupation militaire, et non la fin de la présidence de Vincent ni la disparition immédiate de toute influence américaine.',images.vincent,[...occupationSources,refs.vincentElection,refs.locJohnson],{curriculum:'UA9 — élections de 1930, nationalisme, retrait de 1934 et continuités après l’occupation.',actors:['Assemblée nationale','Union Patriotique','Franklin D. Roosevelt','Garde d’Haïti'],concepts:['nationalisme','autonomie','retrait militaire','continuité économique'],uncertainty:'Les sources diplomatiques américaines et les écrits de Vincent n’ont pas le même point de vue; la fin de l’occupation doit être distinguée d’une souveraineté économique complète.'}),
  make('lescot',1941,'1941–1946','Gouvernements de 1941–1957','Élie Lescot','Président d’Haïti','Élie Lescot gouverne pendant la Seconde Guerre mondiale et quitte le pouvoir après des grèves et mobilisations en janvier 1946.','Le gouvernement s’allie aux États-Unis durant la guerre et soutient la SHADA, un programme de culture du caoutchouc qui bouleverse des terres et des communautés rurales.', ['Renforcement des relations diplomatiques et économiques avec les États-Unis.'], ['Le régime réprime la presse et les oppositions.','Le projet SHADA provoque des expropriations et des tensions paysannes.'], 'Le soulèvement de janvier 1946 contraint Lescot à partir; une junte militaire dirige ensuite le pays.',images.lescot,[refs.postOccupation,refs.frus,refs.casimir],{curriculum:'UA9 — crises, guerres, gouvernements de 1946–1957 et transformations économiques.'}),
  make('lavaud',1946,'Janvier–août 1946','Gouvernements de 1941–1957','Conseil exécutif militaire (Lavaud, Levelt, Magloire)','Junte de transition','Après le départ de Lescot, trois officiers forment un Conseil exécutif militaire qui organise la transition de 1946.','La junte administre le pays au milieu de grèves, de mobilisations étudiantes et d’attentes de changement politique.', ['Organisation d’un retour à un gouvernement civil et d’une élection présidentielle par l’Assemblée.'], ['Le pouvoir reste détenu par les militaires et les transitions dépendent de l’armée.'], 'Dumarsais Estimé devient président en août 1946.',images.lavaudPortrait,[refs.frus,refs.postOccupation,refs.casimir],{gallery:[eventVisual('soulevement-janvier-1946-estime')],curriculum:'UA9 — soulèvement de 1946, transition militaire, Estimé et Magloire.'}),
  make('estime',1946,'1946–1950','Gouvernements de 1941–1957','Dumarsais Estimé','Président d’Haïti, élu par l’Assemblée nationale','Estimé est élu par l’Assemblée après les mobilisations de 1946. Son élection s’inscrit dans les débats haïtiens sur le noirisme et les rapports de couleur en politique.','Le gouvernement développe l’enseignement, soutient des coopératives et des politiques sociales; les projets annoncés et leurs réalisations doivent être distingués. L’exposition internationale de 1949 donne une visibilité nouvelle à Port-au-Prince.', ['Expansion de l’enseignement et politiques sociales, à préciser au moyen de sources haïtiennes contemporaines.','Soutien à des coopératives, hausse de salaires et investissements publics rapportés par les sources secondaires.'], ['Les projets annoncés ne sont pas tous achevés.','Les tensions autour de l’emprunt salarial et de la prolongation du mandat précèdent le coup d’État militaire de 1950. La Library of Congress documente la nationalisation de la concession de bananes de Standard Fruit; elle n’étaye pas une nationalisation de la banque.'], 'Une junte militaire gouverne jusqu’à l’élection de Paul Magloire en décembre 1950.',images.estime,[refs.postOccupation,refs.frus,refs.casimir],{curriculum:'UA9 — Estimé, gouvernements provisoires, constitutions et transformations sociales.',uncertainty:'Des sources secondaires présentent Estimé comme premier président noir élu depuis l’occupation de 1915; cette formule dépend des catégories de couleur mobilisées et doit être contextualisée. Les effets des politiques sociales demandent des sources haïtiennes contemporaines.'}),
  make('magloire',1950,'Décembre 1950–décembre 1956','Gouvernements de 1941–1957','Paul Magloire','Président d’Haïti','Après la junte de 1950, Magloire devient président lors d’un scrutin réservé aux hommes et son gouvernement met en avant les travaux publics et le tourisme.','Le régime développe des infrastructures et organise le Bicentenaire de Port-au-Prince en 1950. Les opposants contestent la répression et les tentatives de prolonger le mandat.', ['Travaux publics, infrastructures urbaines et promotion du tourisme.','Événements culturels et commémoratifs du Bicentenaire de Port-au-Prince.'], ['Le scrutin de 1950 exclut les femmes.','La répression des opposants et le conflit sur le mandat fragilisent le régime.'], 'Magloire quitte le pays en décembre 1956; plusieurs gouvernements de transition se succèdent avant les élections de 1957.',images.magloire,[refs.postOccupation,refs.chronology,refs.casimir],{curriculum:'UA9, p. 94–95 — Magloire, constitutions, économie et changements sociaux.'}),
  make('pierre-louis',1957,'Février 1957','Transitions de 1956–1957','Joseph Nemours Pierre-Louis','Président provisoire','Après le départ de Magloire, le juge Joseph Nemours Pierre-Louis est investi président provisoire en février 1957. Il démissionne après quelques semaines.','Cette succession prend place dans une crise politique où le pouvoir militaire, les partis et les candidats se disputent les conditions d’une élection.', ['Maintien temporaire d’un exécutif civil dans une période de crise.'], ['La brièveté du mandat ne permet pas de stabiliser l’État.'], 'Franck Sylvain lui succède en février 1957.',null,[refs.chronology,refs.postOccupation],{uncertainty:'Les chronologies peuvent diverger sur la date exacte de l’investiture et de la démission.'}),
  make('sylvain',1957,'Février–avril 1957','Transitions de 1956–1957','Franck Sylvain','Président provisoire','Sylvain est président pendant moins de deux mois, dans la crise qui suit la chute de Magloire.','Les gouvernements se succèdent tandis que les syndicats, les partis et l’armée disputent le contrôle de la transition.', ['Poursuite de la transition vers les élections de 1957.'], ['La crise et la pression militaire entraînent rapidement son renversement.'], 'Daniel Fignolé prend la tête d’un gouvernement provisoire en mai 1957.',null,[refs.chronology,refs.postOccupation]),
  make('fignole',1957,'Mai–juin 1957','Transitions de 1956–1957','Daniel Fignolé','Président provisoire','Fignolé, enseignant et dirigeant syndical, est nommé chef du gouvernement provisoire en mai 1957 après des mobilisations populaires.','Son accession traduit la force des syndicats et des quartiers populaires, mais l’armée conserve une capacité d’intervention déterminante.', ['Représentation temporaire de mouvements syndicaux et populaires dans l’exécutif.'], ['Il est contraint de quitter le pouvoir après quelques semaines et part en exil.'], 'Le général Antonio Kébreau prend la tête d’un conseil militaire, qui organise les élections remportées par François Duvalier.',null,[refs.chronology,refs.postOccupation,refs.casimir],{uncertainty:'Les conditions de la démission et de l’exil doivent être présentées à partir de sources croisées.'}),
  make('kebreau',1957,'Juin–octobre 1957','Transitions de 1956–1957','Antonio Kébreau et le Conseil militaire','Conseil militaire de transition','Kébreau dirige le conseil militaire qui contrôle la transition électorale en 1957.','L’armée supervise la période entre le départ de Fignolé et l’entrée en fonction du président élu.', ['Organisation d’une fin formelle à la crise de succession et de l’élection de 1957.'], ['Le processus électoral se déroule sous forte influence militaire et dans un climat de violence politique.'], 'François Duvalier accède à la présidence en octobre 1957.',null,[refs.chronology,refs.duvalier,refs.casimir],{gallery:[images.duvalierCampaign1957],uncertainty:'Une junte n’est pas un président élu; les titulaires doivent être distingués des chefs de l’État provisoire. La galerie montre Duvalier, candidat suivi par le conseil, et non Kébreau.'}),
  make('francois-duvalier',1957,'1957–1971','Régime Duvalier','François Duvalier','Président, puis président à vie','François Duvalier remporte l’élection de 1957, dans un contexte d’intervention de l’armée, puis concentre progressivement le pouvoir et se fait proclamer président à vie en 1964.','Le régime met en place les Volontaires de la Sécurité nationale, dits Tontons Macoutes, et réprime les adversaires. Des programmes de santé rurale et des institutions sont aussi mis en avant par l’État, mais doivent être évalués avec des sources indépendantes.', ['Création de dispensaires et d’actions de santé rurale documentés dans le bilan gouvernemental.','Développement d’un récit politique national autour de l’autorité présidentielle.'], ['Suppression des libertés politiques, répression et exil de nombreux opposants.','Les estimations des victimes varient; tout chiffre doit être attribué à sa source.'], 'Après sa mort en 1971, son fils Jean-Claude lui succède selon une succession dynastique organisée par le régime.',images.duvalier,[...duvalierSources,refs.iachr86],{gallery:[images.duvalier1963],curriculum:'UA9 — pouvoir, économie, société, opposition et transition démocratique; unité du secondaire sur le monde bipolaire.',uncertainty:'L’élection de 1957 est officielle, mais les interventions de l’armée et les violences sont documentées. Le chiffre souvent cité de morts politiques doit toujours être rattaché à l’auteur qui l’avance.'}),
  make('jean-claude-duvalier',1971,'1971–7 février 1986','Régime Duvalier','Jean-Claude Duvalier','Président à vie','À la mort de son père, Jean-Claude Duvalier devient président à vie à l’âge de dix-neuf ans et dirige le pays jusqu’à son départ en exil en février 1986.','Le gouvernement met en avant une ouverture économique et une image de modernisation, tandis que la répression, les détentions et les restrictions de la presse se poursuivent. Des mobilisations populaires et l’effondrement du soutien extérieur précèdent sa chute.', ['Certains investissements et réformes économiques sont engagés pendant la période.'], ['L’hérédité du pouvoir écarte toute alternance électorale.','La Commission interaméricaine documente des atteintes aux droits humains; la responsabilité et les victimes font l’objet de travaux de justice et d’histoire.'], 'Son départ ne rétablit pas immédiatement la démocratie: le Conseil national de gouvernement dirige la transition vers la Constitution de 1987.',null,[...duvalierSources,refs.iachr86],{film:{title:'Actualités filmées américaines sur la succession de Jean-Claude Duvalier (1971)',embedUrl:'https://archive.org/embed/gov.archives.arc.1654747',sourceUrl:'https://archive.org/details/gov.archives.arc.1654747',credit:'U.S. National Archives, ARC 1654747',license:'Domaine public aux États-Unis, œuvre du gouvernement fédéral',warning:'Film produit par les autorités américaines en 1971; il ne montre pas la chute de 1986 et doit être lu comme une source située.',context:'Documente la succession dynastique en 1971, avec un point de vue diplomatique étranger.'},curriculum:'UA9 — les deux périodes Duvalier, société, économie, exil, opposition et transition de 1986–1987.',uncertainty:'Le film de 1971 ne documente pas le départ de 1986. La transition démocratique reste en cours après le départ de Duvalier.'}),
];

export { images as leaderImages, refs as leaderSources };
export default leaders;

